  const name = (p.properties['สินค้า'].title || []).map(t => t.plain_text).join('');
  const link = p.properties['ลิงก์Affiliate'] ? p.properties['ลิงก์Affiliate'].url : '';
  let caption = (p.properties['แคปชัน'] && p.properties['แคปชัน'].rich_text ? p.properties['แคปชัน'].rich_text : []).map(t => t.plain_text).join('');
  const desc = (p.properties['คำบรรยาย'] && p.properties['คำบรรยาย'].rich_text ? p.properties['คำบรรยาย'].rich_text : []).map(t => t.plain_text).join('');
  const sale = p.properties['ราคาลด'] ? p.properties['ราคาลด'].number : null;
  const full = p.properties['ราคาเต็ม'] ? p.properties['ราคาเต็ม'].number : null;
