    caption = '✨ ' + name + '\n' + (priceLine ? priceLine + '\n' : '') + '👉 ' + link + '\n\n#ป้ายยา #ดีลเด็ด (ลิงก์ affiliate)';
  }
  return { json: { page_id: p.id, name: name, link: link, caption: caption, sale: sale, full: full, desc: desc, cat: cat } };
}).filter(i => i.json.caption && i.json.link).slice(0, 6);

