const deal = $('Split Approved').item.json;
const all = $('Split Approved').all().map(x => x.json);
const idx = all.findIndex(a => a.page_id === deal.page_id);
function pick(node, i){ try { const arr = $(node).all(); return (i >= 0 && arr[i]) ? arr[i].json : null; } catch (e) { return null; } }
function errOf(j){ try { const m = (j && j.error && (j.error.message || j.error.error_user_msg)) || (j && j.message) || ''; return String(m).replace(/\s+/g, ' ').slice(0, 70); } catch (e) { return ''; } }

let tg = '❌ ไม่สำเร็จ';
const tv = pick('TG Verify', idx);
if (tv && tv.sent === true) tg = '✅ รูป+แคปชัน';
else if (tv && tv.sent === false) tg = '⚠️ ข้อความล้วน (รูปไม่ผ่าน)';

let fb = '❌ ไม่สำเร็จ';
const fv = pick('FB Verify', idx);
if (fv && fv.sent === true) fb = '✅ รูป+แคปชัน';
else if (fv && fv.sent === false) fb = '⚠️ ข้อความ+ลิงก์ (รูปไม่ผ่าน)';

let thj = null;
try { thj = $('Threads Publish').item.json; } catch (e) { thj = pick('Threads Publish', idx); }
let th;
if (thj && thj.id) {
  let mode = '';
  try { mode = $('Build Threads Post').item.json.mode || ''; } catch (e) {}
  th = (mode === 'TEXT') ? '✅ ข้อความล้วน' : '✅ รูป+แคปชัน';
} else {
  const m = errOf(thj);
  th = '❌ ไม่สำเร็จ' + (m ? ' — ' + m : '');
}

const text = '✅ โพสต์แล้ว: ' + (deal.name || '-') + '\n' +
  '• Telegram: ' + tg + '\n' +
  '• Facebook: ' + fb + '\n' +
  '• Threads: ' + th +
  (deal.link ? '\n' + deal.link : '');
return { json: { alert: text, name: deal.name } };

const d=$('Split Approved').item.json;
let img=null;
try{
  const imgs=$json.images;
  if(Array.isArray(imgs)&&imgs.length){
    const big=imgs.slice().sort((a,b)=>(b.width||0)-(a.width||0))[0];
    if(big&&big.source)img=big.source;
  }
}catch(e){}
let text=(d.caption||'').trim();
// IG กดลิงก์ในแคปชันไม่ได้ -> ตัดบรรทัดที่มีลิงก์ทิ้ง
let lines=text.split('\n').filter(l=>l.indexOf('http')===-1);
// ดึงแฮชแท็กออกจากเนื้อความไปรวมไว้ท้ายโพสต์ที่เดียว + ตัดหมายเหตุ (ลิงก์ affiliate) ที่ไม่มีความหมายบน IG
const found=[];
lines=lines.map(function(l){
  l=l.replace(/\(\s*ลิงก์\s*affiliate\s*\)/g,'');
  const m=l.match(/#[^\s#]+/g);
  if(m)m.forEach(function(t){found.push(t);});
  return l.replace(/#[^\s#]+/g,'').replace(/[ \t]+/g,' ').trim();
});
let body=lines.join('\n').replace(/\n{3,}/g,'\n\n').trim();
const cat=(d.cat||'').trim();
const base=['#ป้ายยา','#ดีลเด็ด','#ของถูก','#รีวิวของดี','#ช้อปปิ้งออนไลน์'];
if(cat)base.push('#'+cat.replace(/\s/g,''));
const tags=[];
found.concat(base).forEach(function(t){if(tags.indexOf(t)===-1)tags.push(t);});
let caption=body+'\n\n🔗 กดลิงก์ในไบโอเพื่อไปที่ร้าน\n\n'+tags.join(' ');
if(caption.length>2100)caption=caption.slice(0,2099);
return { json: { igImage:img, igCaption:caption, hasImage:!!img } };

// IG Reel: สร้าง container Reels → ให้ container deal-video (VPS) เรนเดอร์คลิปแล้วอัปโหลดเข้า rupload เอง
// → รอ Meta ประมวลผล → publish · ล้มขั้นไหนก็ตาม → reelOk:false แล้ว "IG Reel OK?" ส่งไปโพสต์ภาพแบบเดิม (ดีลห้ามหายจาก IG)
// ที่ไม่ส่งไฟล์ผ่าน node นี้เพราะ task runner serialize Buffer เพี้ยน (Meta ตอบ Video Transcoding Error)
// ซอร์สเรนเดอร์: repo deal-poster vps/deal-video/service/server.py
const IG = '17841440317177953';
const V = 'v21.0';
const TOKEN = 'REPLACE_FB_PAGE_TOKEN';
const DRY_RUN = false;
const CREDIT = '🎵 Carefree — Kevin MacLeod (incompetech.com) · CC BY 4.0';
const sleep = ms => new Promise(r => setTimeout(r, ms));
const mask = s => String(s).replace(/EAA[A-Za-z0-9]+/g, '<TOKEN>').slice(0, 500);
const d = $('Split Approved').item.json;
const base = { igImage: $json.igImage, igCaption: $json.igCaption, hasImage: $json.hasImage };
let stage = 'create';
try {
  // ⏱ กันชนเวลา: ทั้ง node เป็น task เดียวของ task runner ซึ่งตัดที่ 300 วิ
  // 20 ก.ย. 69 เกิดจริง: 6 ดีล → timeout กลางคัน → ดีลที่ลง Reels ไปแล้ว 3 ตัวถูกส่งไปโพสต์ภาพซ้ำอีกรอบ
  // ดังนั้นถ้าเวลาจะไม่พอสำหรับดีลถัดไป ให้ยอมถอยไปโพสต์ภาพตั้งแต่ต้น ดีกว่าโดนตัดกลางทาง
  const g = globalThis.__reel || (globalThis.__reel = {});
  if (g.exec !== $execution.id) { g.exec = $execution.id; g.t0 = Date.now(); }
  if ($itemIndex > 0) await sleep(8000);
  const spent = Date.now() - g.t0;
  if (spent > 200000) return { json: { ...base, reelOk: false, reelError: 'budget: ใช้ไป ' + Math.round(spent / 1000) + ' วิ ไม่พอทำคลิปอีกตัว → โพสต์ภาพแทน' } };

  // เครดิตเพลง CC BY ต้องมีทุกโพสต์ — แทรกก่อนบรรทัดแฮชแท็ก
  let cap = String($json.igCaption || '');
  const cut = cap.lastIndexOf('\n\n');
  cap = cut > 0 ? cap.slice(0, cut) + '\n\n' + CREDIT + cap.slice(cut) : cap + '\n\n' + CREDIT;
  if (cap.length > 2200) cap = cap.slice(0, 2200);

  const c = await this.helpers.httpRequest({
    method: 'POST', url: `https://graph.facebook.com/${V}/${IG}/media`,
    qs: { media_type: 'REELS', upload_type: 'resumable', share_to_feed: 'true', caption: cap, access_token: TOKEN },
    json: true, timeout: 30000,
  });
  if (!c || !c.id) throw new Error('no container id');

  stage = 'render+upload';
  const r = await this.helpers.httpRequest({
    method: 'POST', url: 'http://deal-video:8080/render',
    body: { name: d.name, sale: d.sale, full: d.full, desc: d.desc, cat: d.cat, img: $json.igImage,
            upload: { url: c.uri || `https://rupload.facebook.com/ig-api-upload/${V}/${c.id}`, token: TOKEN } },
    json: true, timeout: 300000,
  });
  if (!r || !r.uploaded) throw new Error('upload: ' + JSON.stringify(r));

  stage = 'processing';
  let st = {};
  for (let i = 0; i < 30; i++) {
    await sleep(3000);
    st = await this.helpers.httpRequest({
      method: 'GET', url: `https://graph.facebook.com/${V}/${c.id}`,
      qs: { fields: 'status_code,status', access_token: TOKEN }, json: true, timeout: 20000,
    });
    if (st.status_code === 'FINISHED' || st.status_code === 'ERROR' || st.status_code === 'EXPIRED') break;
  }
  if (st.status_code !== 'FINISHED') throw new Error('status ' + st.status_code + ' ' + (st.status || ''));
  if (DRY_RUN) return { json: { ...base, reelOk: false, dryRun: true, container: c.id, bytes: r.bytes, voice: r.voice, duration: r.duration } };

  stage = 'publish';
  const pub = await this.helpers.httpRequest({
    method: 'POST', url: `https://graph.facebook.com/${V}/${IG}/media_publish`,
    qs: { creation_id: c.id, access_token: TOKEN }, json: true, timeout: 60000,
  });
  if (!pub || !pub.id) throw new Error('no media id');
  return { json: { ...base, reelOk: true, reelId: pub.id, voice: r.voice, duration: r.duration } };
} catch (e) {
  let msg = e && e.message ? e.message : String(e);
  try { if (e.response && e.response.body) msg += ' | ' + JSON.stringify(e.response.body); } catch (x) {}
  return { json: { ...base, reelOk: false, reelError: stage + ': ' + mask(msg) } };
}
